export const projectPhotoSrcSet = (photo: ProjectPhoto) => [
 ...(photo.width > 400 ? [photo.image.replace(/\.webp$/, '-400.webp') + ' 400w'] : []),
 ...(photo.width > 700 ? [photo.image.replace(/\.webp$/, '-700.webp') + ' 700w'] : []),
 photo.image + ' ' + photo.width + 'w',
].join(', ')
